    if y % 2 == 0:
        candidate = y
    else:
        candidate = y - 1

    # Check if candidate is >= x
    if candidate >= x:
        return candidate
    else:
        # Try the next even number down from candidate
        candidate -= 1
        while candidate >= x:
            candidate -= 1
        if candidate < x:
            return -1
        else:
            return candidate

